def find_celebrity(M):
    n = len(M)
    stack = list(range(n))
    while len(stack) > 1:
        a, b = stack.pop(), stack.pop()
        if M[a][b] == 1 and M[b][a] == 0:
            stack.append(b)   # a knows b -> a is out
        elif M[b][a] == 1 and M[a][b] == 0:
            stack.append(a)   # b knows a -> b is out
    if not stack:
        return -1
    cand = stack[0]
    return cand if all(
        M[i][cand] == 1 and M[cand][i] == 0 for i in range(n) if i != cand
    ) else -1

