#include <bits/stdc++.h>
using namespace std;

int celebrity(vector<vector<int>>& M, int n) {
    stack<int> st;
    for (int i = 0; i < n; ++i) st.push(i);
    while (st.size() > 1) {
        int a = st.top(); st.pop();
        int b = st.top(); st.pop();
        if (M[a][b] == 1 && M[b][a] == 0) st.push(b);
        else if (M[b][a] == 1 && M[a][b] == 0) st.push(a);
    }
    if (st.empty()) return -1;
    int cand = st.top();
    for (int i = 0; i < n; ++i)
        if (i != cand && (M[i][cand] == 0 || M[cand][i] == 1)) return -1;
    return cand;
}

